import { effect, onCleanup, signal } from '@vorzelajs/core'
import { accessorOf } from '~/hooks/index.ts'
import type { ReactNode } from '~/lib/types.ts'
import styles from './primitives.module.scss'

export interface DismissableLayerProps {
  children?: ReactNode
  onDismiss: () => void
  enabled?: boolean | (() => boolean)
}

/** Calls `onDismiss` on Escape or an outside pointer press. */
export function DismissableLayer({
  children,
  onDismiss,
  enabled = true,
}: DismissableLayerProps) {
  const [node, setNode] = signal<HTMLDivElement | null>(null)
  const isEnabled = accessorOf(enabled)

  effect(() => {
    if (!isEnabled()) return

    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key !== 'Escape' || event.defaultPrevented) return
      event.preventDefault()
      onDismiss()
    }
    const onPointerDown = (event: PointerEvent): void => {
      const root = node()
      if (!root || root.contains(event.target as Node)) return
      onDismiss()
    }

    document.addEventListener('keydown', onKeyDown)
    document.addEventListener('pointerdown', onPointerDown, true)
    onCleanup(() => {
      document.removeEventListener('keydown', onKeyDown)
      document.removeEventListener('pointerdown', onPointerDown, true)
    })
  })

  return (
    <div ref={(element) => setNode(element as HTMLDivElement)} className={styles.layer}>
      {children}
    </div>
  )
}

import { effect, onCleanup, signal } from '@vorzelajs/core'
import { accessorOf } from '~/hooks/index.ts'
import { cx } from '~/lib/cx.ts'
import type { ReactNode } from '~/lib/types.ts'
import styles from './primitives.module.scss'

const FOCUSABLE = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
  '[contenteditable="true"]',
].join(',')

export interface FocusTrapProps {
  children?: ReactNode
  class?: string
  className?: string
  active?: boolean | (() => boolean)
  restoreFocus?: boolean
}

/** Traps Tab focus and restores focus when the branch is disposed. */
export function FocusTrap({
  children,
  className,
  active = true,
  restoreFocus = true,
}: FocusTrapProps) {
  const [node, setNode] = signal<HTMLDivElement | null>(null)
  const isActive = accessorOf(active)

  effect(() => {
    const root = node()
    if (!root || !isActive()) return

    const previous = document.activeElement as HTMLElement | null
    const items = root.querySelectorAll<HTMLElement>(FOCUSABLE)
    ;(items[0] ?? root).focus()

    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key !== 'Tab') return
      const focusable = Array.from(root.querySelectorAll<HTMLElement>(FOCUSABLE))
      if (focusable.length === 0) {
        event.preventDefault()
        return
      }
      const first = focusable[0] as HTMLElement
      const last = focusable[focusable.length - 1] as HTMLElement
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }

    root.addEventListener('keydown', onKeyDown)
    onCleanup(() => {
      root.removeEventListener('keydown', onKeyDown)
      if (restoreFocus) previous?.focus()
    })
  })

  return (
    <div
      ref={(element) => setNode(element as HTMLDivElement)}
      className={cx(styles.trap, className)}
      tabIndex={-1}
    >
      {children}
    </div>
  )
}

@use 'styles' as vz;

.layer {
  display: contents;
}

.trap {
  outline: none;
}

.fade {
  animation: vz-fade-in var(--vz-fade-duration, 240ms) vz.ease('out')
    var(--vz-fade-delay, 0ms) both;
}

.fade-reduced {
  animation: none;
}

.skip {
  position: fixed;
  top: vz.space(4);
  left: vz.space(4);
  z-index: vz.z('toast');
  padding: vz.space(2) vz.space(4);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('md');
  background: vz.color('primary');
  color: vz.color('primary-foreground');
  font-size: vz.font-size('sm');
  font-weight: 600;
  text-decoration: none;
  box-shadow: vz.elevation(2);
  transform: translateY(-200%);

  &:focus-visible {
    transform: none;
    outline: 2px solid vz.color('ring', 0.6);
    outline-offset: 2px;
  }
}

.sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

.error {
  padding: vz.space(4);
  border: 1px solid vz.color('destructive', 0.3);
  border-radius: vz.radius('lg');
  background: vz.color('destructive', 0.06);
  color: vz.color('destructive');
  font-size: vz.font-size('sm');
  line-height: 1.5;
}

@keyframes vz-fade-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

import { cx } from '~/lib/cx.ts'
import type { HTMLAttributes } from '~/lib/types.ts'
import styles from './primitives.module.scss'

/** Screen-reader-only content. */
export function VisuallyHidden({
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement>) {
  return <span className={cx(styles.sr, className)} {...props} />
}
